$env:NO_PROXY = ".openai.azure.com,10.*,example.com,.example.com,10.0.0.0/8,192.168.0.0/16,localhost,.local,127.0.0.0/8,172.16.0.0/12,134.134.0.0/16,.search.windows.net"
